const { GeminiRotator } = require('/home/node/scripts/gemini-rotation.js');
const { updateCustomer } = require('/home/node/scripts/cvpro-helpers.js');
const { customerId, conversationText } = $input.first().json.body;
const prompt = `Analyze buying intent 0-100 and suggest lead stage (new, qualified, analysis_done, offer_sent, negotiation, won, lost). Return JSON: {"score": int, "suggested_stage": string}. Conversation: ${(conversationText || '').substring(0, 2000)}`;
const rotator = new GeminiRotator(process.env.GEMINI_API_KEYS.split(','));
const result = await rotator.callJSON(prompt, '');
await updateCustomer($http, customerId, {
  buying_intent_score: result.score,
  lead_stage: result.suggested_stage,
});
return [{ json: result }];
